# Indexed symbols and their operations psi, tau, eta and induction (Phase 4, work packages 4.1 and 4.2).
#
# The indexed Burnside group Burn_{n,I}(G) of Kresch-Tschinkel (arXiv:2108.00518 Section 4, arXiv:2105.02929 Section 4)
# is generated by symbols (H in A, Z acting on K, beta, gamma). This file works in the subgroup notation of the package:
#   * H <= A are abelian subgroups of G, Y~ is a subgroup with A <= Y~ <= Z_G(A) (the preimage of the group Y that acts
#     faithfully on one component of K, so the kernel of the action is A),
#   * d is the transcendence degree of K, only its value is stored, the field is not,
#   * beta is a list of n - d - |I| nonzero characters of A, trivial on H, whose common kernel in A is H,
#   * gamma is a family of characters c_i of A indexed by the set I whose restrictions to H have trivial common kernel.
# Characters are stored as dictionaries from the elements of A to Q/Z, so restriction, sums and kernels are plain
# arithmetic. The class is a formal sum, relations (B1) and (B2) are never applied here. Only (O) and (C) are used to
# identify equal symbols, which makes the formal cancellations of Theorem 8.4 of KT-repr visible.
#
# Sources checked against the printed text: psi is Definition 4.2, tau is Example 4.1, eta is Definition 5.8, induction is
# Definition 3.1 of KT-repr. Convention: an element x conjugated by g is x^g = g^-1 x g (the OSCAR convention).

_m1(x::Rational{Int}) = x - fld(numerator(x), denominator(x))

function _subgroup_elements(G, gens)
    gl = elem_type(G)[g for g in gens]
    (isempty(gl) || all(isone, gl)) && return Any[one(G)]
    S, emb = sub(G, gl)
    return Any[emb(x) for x in S]
end

"""
    indexed_character(G, gens, exps)

The character of the abelian subgroup generated by the independent elements `gens` of `G` with values given by `exps`.

`G` is a finite OSCAR group, `gens` a list of independent generators g_1..g_k of an abelian subgroup A (the order of A is
the product of the orders of the g_j) and `exps` integers c_1..c_k, so that the character takes the value
`exp(2 pi i c_j / ord(g_j))` on `g_j`. Returns a `Dict` from the elements of A to the rational `x` in `[0, 1)` with value
`exp(2 pi i x)`, the form used by `IndexedSymbol`.

Throws `ArgumentError` for dependent generators, non commuting generators or a wrong number of exponents.

# Examples

```jldoctest
G = symmetric_group(3)
c3 = cperm(G, [1, 2, 3])
chi = indexed_character(G, [c3], [1])
println(chi[c3], " ", chi[c3^2], " ", chi[one(G)])

# output

1//3 2//3 0//1
```
"""
function indexed_character(G, gens, exps)
    length(gens) == length(exps) || throw(ArgumentError("one exponent is needed for each generator"))
    ords = [Int(order(g)) for g in gens]
    for g in gens, h in gens
        g * h == h * g || throw(ArgumentError("the generators do not commute"))
    end
    els = _subgroup_elements(G, gens)
    prod(ords) == length(els) || throw(ArgumentError("the generators are not independent: |A| = $(length(els)) but the product of the orders is $(prod(ords))"))
    out = Dict{Any,Rational{Int}}()
    for ks in Iterators.product((0:(o - 1) for o in ords)...)
        x = one(G)
        v = 0 // 1
        for (g, k, c, o) in zip(gens, ks, exps, ords)
            x = x * g^k
            v += (c * k) // o
        end
        out[x] = _m1(v)
    end
    length(out) == length(els) || throw(ArgumentError("the generators are not independent"))
    return out
end

"""
    IndexedSymbol(G, Hgens, Agens, Ygens, d, beta, gamma)

An indexed symbol `(H in A, Y~, beta, gamma)` of the group `G` with a field of transcendence degree `d`.

`Hgens`, `Agens` and `Ygens` are lists of elements of `G` generating the subgroups `H`, `A` and `Y~`, with `H <= A <= Y~`,
`A` abelian and `Y~` inside the centralizer of `A`. `beta` is a vector of characters of `A` (dictionaries from the elements
of `A` to `Q/Z`, see `indexed_character`) and `gamma` a `Dict` from an index to a character of `A`. The conditions of the
definition are checked: `beta` consists of nonzero characters trivial on `H` whose common kernel in `A` is exactly `H`,
the restrictions of the characters of `gamma` to `H` have trivial common kernel (so `H` is trivial when `gamma` is empty),
every character is a homomorphism of `A` to `Q/Z`, and `d >= 0`. The elements of the three subgroups are stored.

Throws `ArgumentError` when a condition fails.

# Examples

```jldoctest
G = symmetric_group(3)
t = perm(G, [2, 1, 3])
sgn = indexed_character(G, [t], [1])
s = IndexedSymbol(G, [], [t], [t], 0, [sgn], Dict(0 => Dict(one(G) => 0 // 1, t => 0 // 1)))
println(length(s.A), " ", length(s.H), " ", s.d)

# output

2 1 0
```
"""
struct IndexedSymbol
    G::Any
    H::Vector{Any}
    A::Vector{Any}
    Y::Vector{Any}
    d::Int
    beta::Vector{Dict{Any,Rational{Int}}}
    gamma::Dict{Int,Dict{Any,Rational{Int}}}
    # The only way to call the raw constructor is with the sentinel `Val(:raw)`, so that every public call goes through the
    # validating constructor below (which also closes the three lists of generators to subgroups).
    function IndexedSymbol(G, H, A, Y, d::Int, beta, gamma, ::Val{:raw})
        return new(G, H, A, Y, d, beta, gamma)
    end
end

function _norm_char(A, c, what)
    for a in A
        haskey(c, a) || throw(ArgumentError("$what is not defined on every element of A"))
    end
    length(c) == length(A) || throw(ArgumentError("$what has values outside A"))
    out = Dict{Any,Rational{Int}}(a => _m1(Rational{Int}(c[a])) for a in A)
    for a in A, b in A
        out[a * b] == _m1(out[a] + out[b]) || throw(ArgumentError("$what is not a homomorphism of A to Q/Z"))
    end
    return out
end

function IndexedSymbol(G, Hgens, Agens, Ygens, d::Integer, beta, gamma)
    d >= 0 || throw(ArgumentError("d must be nonnegative"))
    H = _subgroup_elements(G, Hgens)
    A = _subgroup_elements(G, Agens)
    Y = _subgroup_elements(G, vcat(Any[g for g in Agens], Any[g for g in Ygens]))
    Aset = Set(A)
    all(h in Aset for h in H) || throw(ArgumentError("H is not contained in A"))
    for a in A, b in A
        a * b == b * a || throw(ArgumentError("A is not abelian"))
    end
    for y in Y, a in A
        y * a == a * y || throw(ArgumentError("Y~ is not contained in the centralizer of A"))
    end
    Hset = Set(H)
    bs = Dict{Any,Rational{Int}}[_norm_char(A, c, "a character of beta") for c in beta]
    for c in bs
        any(!iszero(v) for v in values(c)) || throw(ArgumentError("a character of beta is zero"))
        all(iszero(c[h]) for h in H) || throw(ArgumentError("a character of beta is not trivial on H"))
    end
    Set(a for a in A if all(iszero(c[a]) for c in bs)) == Hset ||
        throw(ArgumentError("the characters of beta do not generate the dual of A/H"))
    gm = Dict{Int,Dict{Any,Rational{Int}}}(Int(i) => _norm_char(A, c, "a character of gamma") for (i, c) in gamma)
    all(isone(h) for h in Set(h for h in H if all(iszero(c[h]) for c in values(gm)))) ||
        throw(ArgumentError("the restrictions of gamma to H do not generate the dual of H"))
    return IndexedSymbol(G, H, A, Y, Int(d), bs, gm, Val(:raw))
end

function Base.show(io::IO, s::IndexedSymbol)
    print(io, "IndexedSymbol(|H| = ", length(s.H), ", |A| = ", length(s.A), ", |Y~| = ", length(s.Y), ", d = ", s.d,
        ", ", length(s.beta), " beta, gamma indices ", sort(collect(keys(s.gamma))), ")")
end

"""
    IndexedClass(G, n, I)

A formal sum of indexed symbols of `G`, an element of `Burn_{n,I}(G)` before any relation is applied.

`G` is a finite OSCAR group, `n` the dimension and `I` the list of indices (integers). Add with `push!(cls, sym)` or
`push!(cls, coef, sym)`. A symbol is accepted when it has `n - d - |I|` characters in `beta` and its `gamma` is indexed
exactly by `I`. Symbols are identified when some element of `G` conjugates one to the other (relation (C)) and
after reordering the characters of `beta` (relation (O)), and equal symbols are added, so the formal cancellations of
Theorem 8.4 of Kresch-Tschinkel are visible. Relations (B1) and (B2) are not applied. Classes support `+`, `-`, integer
`*`, `==`, `iszero` and `length` (the number of distinct nonzero symbols).

Throws `ArgumentError` for a symbol of another group, a wrong number of characters or a wrong index set.

# Examples

```jldoctest
G = symmetric_group(3)
println(iszero(IndexedClass(G, 2, [0])))

# output

true
```
"""
mutable struct IndexedClass
    G::Any
    n::Int
    I::Vector{Int}
    elems::Vector{Any}
    idx::Dict{Any,Int}
    terms::Dict{Any,Tuple{Int,IndexedSymbol}}
end

function IndexedClass(G, n::Integer, I)
    el = Any[g for g in G]
    return IndexedClass(G, Int(n), sort!(Int[i for i in I]), el, Dict{Any,Int}(g => i for (i, g) in enumerate(el)),
        Dict{Any,Tuple{Int,IndexedSymbol}}())
end

function _ikey(cls::IndexedClass, s::IndexedSymbol, g)
    idx = cls.idx
    cj(x) = idx[x^g]
    chars(c) = sort!(Tuple{Int,Rational{Int}}[(cj(x), v) for (x, v) in c])
    h = sort!(Int[cj(x) for x in s.H])
    a = sort!(Int[cj(x) for x in s.A])
    y = sort!(Int[cj(x) for x in s.Y])
    b = sort!([chars(c) for c in s.beta])
    gm = [(i, chars(c)) for (i, c) in sort!(collect(s.gamma); by = first)]
    return (h, a, y, s.d, b, gm)
end

function _icanonical(cls::IndexedClass, s::IndexedSymbol)
    best = nothing
    for g in cls.elems
        k = _ikey(cls, s, g)
        if best === nothing || k < best
            best = k
        end
    end
    return best
end

function Base.push!(cls::IndexedClass, coef::Integer, s::IndexedSymbol)
    s.G == cls.G || throw(ArgumentError("the symbol belongs to a different group than the class"))
    sort!(collect(keys(s.gamma))) == cls.I ||
        throw(ArgumentError("the indices of gamma are $(sort!(collect(keys(s.gamma)))) but the class has the index set $(cls.I)"))
    length(s.beta) == cls.n - s.d - length(cls.I) ||
        throw(ArgumentError("a symbol with d = $(s.d) in dimension $(cls.n) with $(length(cls.I)) indices needs $(cls.n - s.d - length(cls.I)) characters in beta, it has $(length(s.beta))"))
    coef == 0 && return cls
    k = _icanonical(cls, s)
    old = get(cls.terms, k, (0, s))
    c = old[1] + Int(coef)
    if c == 0
        delete!(cls.terms, k)
    else
        cls.terms[k] = (c, old[2])
    end
    return cls
end
Base.push!(cls::IndexedClass, s::IndexedSymbol) = push!(cls, 1, s)

Base.length(cls::IndexedClass) = length(cls.terms)
Base.iszero(cls::IndexedClass) = isempty(cls.terms)
Base.copy(cls::IndexedClass) = IndexedClass(cls.G, cls.n, cls.I, cls.elems, cls.idx, copy(cls.terms))

function _same_shape(a::IndexedClass, b::IndexedClass)
    a.G == b.G || throw(ArgumentError("the classes belong to different groups"))
    (a.n == b.n && a.I == b.I) || throw(ArgumentError("the classes have a different dimension or index set"))
end

function Base.:+(a::IndexedClass, b::IndexedClass)
    _same_shape(a, b)
    out = copy(a)
    for (_, (c, s)) in b.terms
        push!(out, c, s)
    end
    return out
end
function Base.:*(c::Integer, a::IndexedClass)
    out = IndexedClass(a.G, a.n, a.I, a.elems, a.idx, Dict{Any,Tuple{Int,IndexedSymbol}}())
    c == 0 && return out
    for (k, (x, s)) in a.terms
        out.terms[k] = (Int(c) * x, s)
    end
    return out
end
Base.:-(a::IndexedClass) = (-1) * a
Base.:-(a::IndexedClass, b::IndexedClass) = a + (-b)
function Base.:(==)(a::IndexedClass, b::IndexedClass)
    (a.G == b.G && a.n == b.n && a.I == b.I) || return false
    length(a.terms) == length(b.terms) || return false
    for (k, (c, _)) in a.terms
        haskey(b.terms, k) && b.terms[k][1] == c || return false
    end
    return true
end
Base.hash(a::IndexedClass, h::UInt) = hash((a.n, a.I, sort([(k, c) for (k, (c, _)) in a.terms])), h)

function Base.show(io::IO, cls::IndexedClass)
    print(io, "IndexedClass(n = ", cls.n, ", I = ", cls.I, ", ", length(cls.terms), " symbols)")
    for (_, (c, s)) in sort!(collect(cls.terms); by = first)
        print(io, "\n  ", c, " * (|H| = ", length(s.H), ", |A| = ", length(s.A), ", |Y~| = ", length(s.Y), ", d = ", s.d,
            ", ", length(s.beta), " beta)")
    end
end

"""
    indexed_psi(cls, J)

The homomorphism `psi_{I,J}` of Definition 4.2 of Kresch-Tschinkel, from `Burn_{n,I}(G)` to `Burn_{n,J}(G)`.

`cls` is an `IndexedClass` with index set `I` and `J` a subset of `I` (a list of integers). A symbol with some `c_i`, `i`
in `I` minus `J`, equal to zero on `A` goes to zero. Otherwise `H` is replaced by its intersection with the kernels of those
`c_i`, the characters `c_i` for `i` in `I` minus `J` are appended to `beta` (in increasing order of `i`) and `gamma` is
restricted to `J`. The field is untouched, so `d` and `Y~` are unchanged. Returns an `IndexedClass` with index set `J`.

Throws `ArgumentError` when `J` is not a subset of the index set. Functoriality `psi_{J,K} psi_{I,J} = psi_{I,K}` holds.

# Examples

```jldoctest
G = symmetric_group(3)
t = perm(G, [2, 1, 3])
e = Dict(one(G) => 0 // 1, t => 0 // 1)
sgn = indexed_character(G, [t], [1])
cls = IndexedClass(G, 2, [0, 1])
push!(cls, IndexedSymbol(G, [t], [t], [t], 0, [], Dict(0 => sgn, 1 => sgn)))
out = indexed_psi(cls, [0])
println(out.I, " ", length(out))

# output

[0] 1
```
"""
function indexed_psi(cls::IndexedClass, J)
    Jl = sort!(Int[j for j in J])
    all(j in cls.I for j in Jl) || throw(ArgumentError("J must be a subset of the index set $(cls.I)"))
    length(unique(Jl)) == length(Jl) || throw(ArgumentError("J has repeated indices"))
    out = IndexedClass(cls.G, cls.n, Jl, cls.elems, cls.idx, Dict{Any,Tuple{Int,IndexedSymbol}}())
    rem = [i for i in cls.I if !(i in Jl)]
    for (_, (coef, s)) in cls.terms
        any(all(iszero(v) for v in values(s.gamma[i])) for i in rem) && continue
        H = Any[h for h in s.H if all(iszero(s.gamma[i][h]) for i in rem)]
        beta = vcat(s.beta, Dict{Any,Rational{Int}}[s.gamma[i] for i in rem])
        gm = Dict{Int,Dict{Any,Rational{Int}}}(j => s.gamma[j] for j in Jl)
        push!(out, coef, IndexedSymbol(s.G, H, s.A, s.Y, s.d, beta, gm))
    end
    return out
end

# contributions[j] is the list of indices i whose character is added into the new j-th character
function _tau_contributions(I, J)
    Il = sort!(Int[i for i in I])
    Jl = sort!(Int[j for j in J])
    out = Dict{Int,Vector{Int}}()
    for j in Il
        if j in Jl
            out[j] = [i for i in Il if i <= j && minimum(a for a in Jl if a >= i) == j]
        else
            out[j] = [j]
        end
    end
    return out
end

"""
    indexed_tau_matrix(I, J)

The matrix of the automorphism `tau_{I,J}` of `Z^I` of Example 4.1 of Kresch-Tschinkel in the standard basis.

`I` is a list of indices and `J` a subset. Returns an integer matrix `T` with rows and columns ordered by increasing index,
where column `j` holds the coordinates of `tau(e_j)`: `tau(e_j)` is the sum of the `e_i` with `i <= j` such that the smallest
element of `J` that is `>= i` is `j`, if `j` is in `J`, and `e_j` if not. It is unimodular.

# Examples

```jldoctest
println(indexed_tau_matrix([0, 1, 2], [0, 2]))

# output

[1 0 0; 0 1 1; 0 0 1]
```
"""
function indexed_tau_matrix(I, J)
    Il = sort!(Int[i for i in I])
    c = _tau_contributions(Il, J)
    T = zeros(Int, length(Il), length(Il))
    for (jc, j) in enumerate(Il), i in c[j]
        T[findfirst(==(i), Il), jc] = 1
    end
    return T
end

"""
    indexed_tau(cls, J)

The automorphism `tau_{I,J}` of Example 4.1 of Kresch-Tschinkel applied to a class: `gamma` is replaced by `gamma` composed with `tau`.

`cls` is an `IndexedClass` with index set `I` and `J` a subset of `I`. The new character at an index `j` of `J` is the sum of
the characters `c_i` with `i <= j` such that the smallest element of `J` that is `>= i` is `j` (the retained index absorbs the
omitted indices since the previous retained one, in the direction of the next retained index). The characters at the indices
outside `J` do not change. Example: `I = {0, 1, 2}` and `J = {0, 2}` send `(c0, c1, c2)` to `(c0, c1, c1 + c2)`. Returns an
`IndexedClass` with the same index set. In Theorem 8.4 it is applied before `indexed_psi`.

Throws `ArgumentError` when `J` is not a subset of the index set.

# Examples

```jldoctest
G = cyclic_group(PermGroup, 5)
g = gen(G, 1)
c(k) = indexed_character(G, [g], [k])
cls = IndexedClass(G, 4, [0, 1, 2])
push!(cls, IndexedSymbol(G, [], [g], [g], 0, [c(1)], Dict(0 => c(0), 1 => c(1), 2 => c(2))))
out = indexed_tau(cls, [0, 2])
s = first(values(out.terms))[2]
println(round.(Int, 5 .* [s.gamma[0][g], s.gamma[1][g], s.gamma[2][g]]))

# output

[0, 1, 3]
```
"""
function indexed_tau(cls::IndexedClass, J)
    Jl = sort!(Int[j for j in J])
    all(j in cls.I for j in Jl) || throw(ArgumentError("J must be a subset of the index set $(cls.I)"))
    con = _tau_contributions(cls.I, Jl)
    out = IndexedClass(cls.G, cls.n, cls.I, cls.elems, cls.idx, Dict{Any,Tuple{Int,IndexedSymbol}}())
    for (_, (coef, s)) in cls.terms
        gm = Dict{Int,Dict{Any,Rational{Int}}}()
        for j in cls.I
            gm[j] = Dict{Any,Rational{Int}}(a => _m1(sum((s.gamma[i][a] for i in con[j]); init = 0 // 1)) for a in s.A)
        end
        push!(out, coef, IndexedSymbol(s.G, s.H, s.A, s.Y, s.d, s.beta, gm))
    end
    return out
end

"""
    indexed_reindex(cls, newI)

Relabel the index set by the order preserving bijection onto `newI`.

`cls` is an `IndexedClass` and `newI` a list of integers with as many elements as the index set of `cls`. The smallest index
goes to the smallest element of `newI` and so on, as in the re-indexing of Theorem 8.4 of Kresch-Tschinkel. Returns an
`IndexedClass` with index set `newI`.

Throws `ArgumentError` when the sizes differ.
"""
function indexed_reindex(cls::IndexedClass, newI)
    nl = sort!(Int[i for i in newI])
    length(nl) == length(cls.I) || throw(ArgumentError("the new index set has a different size"))
    length(unique(nl)) == length(nl) || throw(ArgumentError("the new index set has repeated indices"))
    mp = Dict(o => n for (o, n) in zip(cls.I, nl))
    out = IndexedClass(cls.G, cls.n, nl, cls.elems, cls.idx, Dict{Any,Tuple{Int,IndexedSymbol}}())
    for (_, (coef, s)) in cls.terms
        push!(out, coef, IndexedSymbol(s.G, s.H, s.A, s.Y, s.d, s.beta, Dict(mp[i] => c for (i, c) in s.gamma)))
    end
    return out
end

"""
    indexed_induce(cls, G, f)

The induction `ind_L^G` of Definition 3.1 of Kresch-Tschinkel, for a subgroup `L` of `G` given by an injective homomorphism `f`.

`cls` is an `IndexedClass` of a group `L`, `G` a finite OSCAR group and `f` a function (for example the embedding returned by
`sub`) sending the elements of `L` to elements of `G`. In subgroup notation the data of every symbol are unchanged, the
subgroups and characters are transported by `f`, and the symbols are now identified up to conjugation in `G`. Returns an
`IndexedClass` of `G` with the same dimension and index set. The map `f` is not checked to be a homomorphism.
"""
function indexed_induce(cls::IndexedClass, G, f)
    out = IndexedClass(G, cls.n, cls.I)
    mv(c) = Dict{Any,Rational{Int}}(f(a) => v for (a, v) in c)
    for (_, (coef, s)) in cls.terms
        push!(out, coef, IndexedSymbol(G, Any[f(x) for x in s.H], Any[f(x) for x in s.A], Any[f(x) for x in s.Y], s.d,
            Dict{Any,Rational{Int}}[mv(c) for c in s.beta], Dict(i => mv(c) for (i, c) in s.gamma)))
    end
    return out
end

"""
    indexed_eta(cls, Hgens; drop_generic = true)

The homomorphism `eta_I` of Definition 5.8 of Kresch-Tschinkel for a central subgroup, followed by the passage to `BC`.

`cls` is an `IndexedClass` of a group `G` whose symbols all have first subgroup `H` equal to the subgroup generated by
`Hgens`, and `H` must be central in `G` (the case of `P(V)` with the scalar subgroup `H = C`). A symbol `(H in A, Y~, beta,
gamma)` goes to the symbol `(A/H, Y~/H, beta)` of `G/H`, which is a `BCSymbol` of the quotient group (characters of `A` trivial
on `H` descend). Returns `(cls_bc, Q, proj, dropped)` with `cls_bc` a `BCClass(Q, n - |I|)`, `Q` the quotient group (the group `G`
itself when `H` is trivial), `proj` the quotient map (the identity function when `H` is trivial) and `dropped` the number of
symbols that were not included because `A = H`: their first subgroup in `G/H` is trivial, they are the generic symbols
`(triv, Y, ())`, which the package leaves out of every `BCClass` (the generic symbol of `toric_class` is omitted for the same
reason). With `drop_generic = false` such a symbol raises an `ArgumentError` instead.

Throws `ArgumentError` when a symbol has a different `H` or `H` is not central.

# Examples

```jldoctest
G = symmetric_group(3)
t = perm(G, [2, 1, 3])
sgn = indexed_character(G, [t], [1])
cls = IndexedClass(G, 2, [0])
push!(cls, IndexedSymbol(G, [], [t], [t], 0, [sgn], Dict(0 => Dict(one(G) => 0 // 1, t => 0 // 1))))
out, Q, proj, dropped = indexed_eta(cls, [])
println(out.n, " ", length(out.terms), " ", dropped)

# output

1 1 0
```
"""
function indexed_eta(cls::IndexedClass, Hgens; drop_generic::Bool = true)
    G = cls.G
    Hel = _subgroup_elements(G, Hgens)
    for h in Hel, g in cls.elems
        h * g == g * h || throw(ArgumentError("H must be central in G"))
    end
    Hset = Set(Hel)
    trivial = length(Hel) == 1
    local Q, proj
    if trivial
        Q = G
        proj = identity
    else
        HS, _ = sub(G, elem_type(G)[h for h in Hel])
        Q, proj = quo(G, HS)
    end
    Qg = gapobj(Q)
    out = BCClass(Q, cls.n - length(cls.I))
    dropped = 0
    for (_, (coef, s)) in cls.terms
        Set(s.H) == Hset || throw(ArgumentError("a symbol has a different first subgroup H"))
        Aimg = unique(Any[proj(a) for a in s.A])
        if length(Aimg) == 1
            drop_generic || throw(ArgumentError("a symbol with A = H has no BC image"))
            dropped += 1
            continue
        end
        Bg = GAP.Globals.Subgroup(Qg, GAP.GapObj(Any[GAP.GapObj(b) for b in Aimg]))
        ind = GAP.Globals.IndependentGeneratorsOfAbelianGroup(Bg)
        hq = Any[Oscar.group_element(Q, ind[i]) for i in 1:length(ind)]
        pre = Any[first(a for a in s.A if proj(a) == q) for q in hq]
        ords = [Int(order(q)) for q in hq]
        betas = Vector{Int}[]
        for c in s.beta
            v = Int[]
            for (a, o) in zip(pre, ords)
                x = c[a] * o
                denominator(x) == 1 || error("a character of beta does not descend to A/H")
                push!(v, mod(Int(numerator(x)), o))
            end
            push!(betas, v)
        end
        Yimg = unique(Any[proj(y) for y in s.Y])
        Yg = GAP.Globals.Subgroup(Qg, GAP.GapObj(Any[GAP.GapObj(y) for y in Yimg]))
        sg = GAP.Globals.SmallGeneratingSet(Yg)
        yq = Any[Oscar.group_element(Q, sg[i]) for i in 1:length(sg)]
        push!(out, coef, BCSymbol(Q, hq, yq, betas))
    end
    return out, Q, proj, dropped
end
